export type ForecastEntry = { time: number; label: string; summary: string; details: string };
export type ForecastDay = { key: string; label: string; entries: ForecastEntry[] };

/** Group supplied periods in the location's calendar, without inventing missing days. */
export function forecastDays(entries: ForecastEntry[], timeZone: string): ForecastDay[] {
	const key = new Intl.DateTimeFormat('en-CA', {
		timeZone,
		year: 'numeric',
		month: '2-digit',
		day: '2-digit'
	});
	const label = new Intl.DateTimeFormat('en-US', {
		timeZone,
		weekday: 'short',
		month: 'short',
		day: 'numeric'
	});
	const days = new Map<string, ForecastDay>();
	for (const entry of entries
		.filter((e) => Number.isFinite(e.time))
		.toSorted((a, b) => a.time - b.time)) {
		const id = key.format(entry.time);
		if (!days.has(id)) days.set(id, { key: id, label: label.format(entry.time), entries: [] });
		days.get(id)!.entries.push(entry);
	}
	return [...days.values()].slice(0, 7);
}

import type { LocationInput, WeatherPeriod, CurrentWeather } from './types.js';

type NwsPoint = {
	properties: {
		forecast: string;
		relativeLocation?: {
			properties?: {
				city?: string;
				state?: string;
			};
		};
	};
};

type NwsForecast = {
	properties: {
		periods: WeatherPeriod[];
	};
};

const headers = {
	Accept: 'application/geo+json',
	'User-Agent': 'wxcn/0.1 (https://github.com/wxcn/wxcn)'
};

export async function fetchWeatherForecast(location: LocationInput): Promise<WeatherPeriod[]> {
	const point = await fetch(
		`https://api.weather.gov/points/${location.latitude.toFixed(4)},${location.longitude.toFixed(4)}`,
		{ headers }
	);

	if (!point.ok) {
		throw new Error(`NWS point lookup failed with ${point.status}`);
	}

	const pointData = (await point.json()) as NwsPoint;
	const forecast = await fetch(pointData.properties.forecast, { headers });

	if (!forecast.ok) {
		throw new Error(`NWS forecast lookup failed with ${forecast.status}`);
	}

	const forecastData = (await forecast.json()) as NwsForecast;
	return forecastData.properties.periods;
}

